import sys

data = sys.stdin.read().split()
n, m, k = int(data[0]), int(data[1]), int(data[2])
edges = [(int(data[3 + 3 * i]), int(data[4 + 3 * i]), int(data[5 + 3 * i])) for i in range(m)]
cands = sorted(set([0] + [e[2] for e in edges]))
for t in cands:
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if w > t:
            adj[u].append(v)
            adj[v].append(u)
    seen = [False] * n
    comps = 0
    for s in range(n):
        if not seen[s]:
            comps += 1
            seen[s] = True
            stack = [s]
            while stack:
                x = stack.pop()
                for y in adj[x]:
                    if not seen[y]:
                        seen[y] = True
                        stack.append(y)
    if comps >= k:
        print(t)
        break

